class ComputePersistenceDiagram(Node):
    def __init__(self, parent_node_id : str):
        super().__init__(parent_node_id, types.Scalar, types.PersistenceDiagram, locals())

    @classmethod
    def chat_description(cls):
        return "queued computing persistence diagram."

    @classmethod
    def guardrails(cls):
        return [piecewise_linear_guardrail]

    @classmethod
    def description(cls):
        return 'Computes the piecewise-linear persistence diagram of a sclar field. It uses the FTM backend which shows ' \
               'the 0 and D-1 order persistence diagram from the sublevel set filtration.'

    @classmethod
    def param_descriptions(cls):
        return {'parent_node_id': 'The id of a node of type scalar that represents the scalar field '
                           'whose piecewise-linear persistence diagram we are computing.'}

    def _evaluation_logic(self, parent_data, time_step):

        pd = ttk.TTKPersistenceDiagram(Input=parent_data.data)
        pd.ScalarField = ['POINTS', 'Scalars_']
        pd.InputOffsetField = ['POINTS', 'Scalars_']
        pd.Backend = 'FTM (IEEE TPSD 2019)'

        return types.PersistenceDiagram(pd)

class EmbedPersistenceDiagram(Node):
    def __init__(self, parent_node_id : str, ball_radius : float = 0.02, tube_radius : float = 0.01):
        super().__init__(parent_node_id, types.PersistenceDiagram, types.PersistenceDiagramEmbedding, locals())
        self.ball_radius = ball_radius
        self.tube_radius = tube_radius

    @classmethod
    def chat_description(cls):
        return "queued embedding persistence diagram"

    @classmethod
    def description(cls):
        return 'Computes a geometric embedding of a persistence diagram.'

    @classmethod
    def param_descriptions(cls):
        return {'parent_node_id': 'The id of a node of type persistence_diagram that we are '
                           'embedding.',
         'ball_radius': 'The radius of the balls in the visualization as a fraction of the '
                        'function range (where 1.0 is the entire range).',
         'tube_radius': 'The radius of the tubes in the visualization as a percentage of the '
                        'function range (where 1.0 is the entire range).'}

    def compatible_to_visualize(self, other):
        return False, "persistence diagram must be visualized by itself."

    def _evaluation_logic(self, parent_data, time_step):

        diagram = PointAndCellIds(Input=parent_data.diagram)
        diagram.GenerateCellIds = 0

        diagram_vtk = servermanager.Fetch(diagram)
        range_ = diagram_vtk.GetCellData().GetArray("Persistence").GetTuple1(0)
        numCells = diagram_vtk.GetNumberOfCells()
        ids_array = diagram_vtk.GetPointData().GetArray("PointIds")

        ids = []
        colors = {}
        color_rng = deterministic_rng("persistence-diagram-colors")

        for i in range(numCells-1):
            c = diagram_vtk.GetCell(i)
            pid1 = c.GetPointIds().GetId(0)
            pid2 = c.GetPointIds().GetId(1)
            pid1 = ids_array.GetTuple1(pid1)
            pid2 = ids_array.GetTuple1(pid2)

            color = (color_rng.random(), color_rng.random(), color_rng.random())

            ids.append(pid1)
            ids.append(pid2)
            colors[pid1] = color
            colors[pid2] = color

        ids.sort()
        color_list = [tuple_to_hex(colors[id_]) for id_ in ids]
        lut = color_list_to_lut(color_list)

        return types.PersistenceDiagramEmbedding(diagram, lut, self.ball_radius * range_, self.tube_radius * range_)

